def test_verify_catches_a_silent_drop() -> None:
    backend = MemoryBackend(silently_drop=["CATEGORIES"])
    collection = backend.collection("default")
    task = Task.new(summary="x", categories=["work"])
    collection.add(task)  # not verified: nobody notices
